import json
from itertools import permutations

def solve():
    houses = [1,2,3,4,5,6]

    Names = ["Alice", "Eric", "Bob", "Peter", "Arnold", "Carol"]
    Heights = ["very tall", "tall", "super tall", "average", "very short", "short"]
    Phones = ["oneplus 9", "google pixel 6", "samsung galaxy s21", "iphone 13", "huawei p50", "xiaomi mi 11"]

    # Utility to build inverse maps
    def invert_map(m):
        return {v:k for k,v in m.items()}

    # Final verification of all clues on a complete assignment
    def verify_complete(name_at, height_at, phone_at):
        pos_name = invert_map(name_at)
        pos_height = invert_map(height_at)
        pos_phone = invert_map(phone_at)

        # 1. Bob is directly left of the person who is tall.
        if pos_name["Bob"] + 1 != pos_height["tall"]:
            return False

        # 2. Peter is somewhere to the left of the person who uses an iPhone 13.
        if not (pos_name["Peter"] < pos_phone["iphone 13"]):
            return False

        # 3. The person who is very short is somewhere to the right of the person who uses a Google Pixel 6.
        if not (pos_height["very short"] > pos_phone["google pixel 6"]):
            return False

        # 4. Carol is the person who is very tall.
        if pos_name["Carol"] != pos_height["very tall"]:
            return False

        # 5. There is one house between the person who uses a Google Pixel 6 and the person who is short.
        if abs(pos_phone["google pixel 6"] - pos_height["short"]) != 2:
            return False

        # 6. The person who uses a Samsung Galaxy S21 is not in the first house.
        if pos_phone["samsung galaxy s21"] == 1:
            return False

        # 7. The person who uses a OnePlus 9 is directly left of the person who is short.
        if pos_phone["oneplus 9"] + 1 != pos_height["short"]:
            return False

        # 8. The person who is tall is Arnold.
        if pos_name["Arnold"] != pos_height["tall"]:
            return False

        # 9. The person who is super tall is in the first house.
        if pos_height["super tall"] != 1:
            return False

        # 10. The person who uses a Xiaomi Mi 11 is Carol.
        if pos_phone["xiaomi mi 11"] != pos_name["Carol"]:
            return False

        # 11. The person who uses a Google Pixel 6 is somewhere to the right of Eric.
        if not (pos_phone["google pixel 6"] > pos_name["Eric"]):
            return False

        # 12. The person who is short is in the sixth house.
        if pos_height["short"] != 6:
            return False

        return True

    # Step 1: Enumerate possible height assignments with immediate constraints.
    # Fixed by clues:
    # - super tall in house 1 (clue 9)
    # - short in house 6 (clue 12)
    # From clues 3 and 5 with GP6 later at 4, we will enforce very short at 5 after phones fixed,
    # but we can anticipate given GP6 will be 4 due to 12&5. We'll enforce after confirming GP6 placement.
    solutions = []
    heights_fixed = {1: "super tall", 6: "short"}
    remaining_heights = ["very tall", "tall", "average", "very short"]
    # positions to fill for heights: 2,3,4,5
    for perm in permutations(remaining_heights, 4):
        height_at = {**heights_fixed}
        for idx, h in zip([2,3,4,5], perm):
            height_at[idx] = h

        # Proceed to phones
        # Step 2: Phone assignments with constraints:
        # - Samsung not in 1 (clue 6)
        # - OnePlus 9 directly left of short at 6 -> OnePlus 9 at 5 (clue 7 + 12)
        # - One house between GP6 and short (6) -> GP6 at 4 (clue 5 + 12)
        phone_at = {i: None for i in houses}
        phone_at[5] = "oneplus 9"
        phone_at[4] = "google pixel 6"

        # Enforce clue 3 now: very short must be to the right of GP6 (at 4) -> very short at 5 or 6.
        # But height_at[6] is "short" so very short must be 5.
        if height_at[5] != "very short":
            continue

        # Clues 4 and 10: Carol is very tall and uses Xiaomi Mi 11 -> very tall house must have Xiaomi.
        pos_vt = None
        for k,v in height_at.items():
            if v == "very tall":
                pos_vt = k
                break
        # If very tall is at 4, conflict with GP6 at 4 (can't also be Xiaomi), so skip
        if pos_vt == 4:
            continue
        # Assign Xiaomi to the very tall house
        phone_at[pos_vt] = "xiaomi mi 11"

        # Remaining phones to assign
        remaining_phones = set(Phones) - {"oneplus 9", "google pixel 6", "xiaomi mi 11"}
        remaining_positions = [1,2,3,6]
        if pos_vt in remaining_positions:
            remaining_positions.remove(pos_vt)

        # Ensure Samsung is not in 1
        for perm_phones in permutations(list(remaining_phones), len(remaining_positions)):
            # Build tentative phone map
            tmp_phone_at = dict(phone_at)
            ok = True
            for pos, ph in zip(remaining_positions, perm_phones):
                tmp_phone_at[pos] = ph
            # Fill the leftover position among [1,2,3,6] if any remains (but should be exact match)
            # Validate Samsung not in 1
            if tmp_phone_at[1] == "samsung galaxy s21":
                ok = False
            if not ok:
                continue

            # Now names assignment with constraints:
            # Clue 8: tall is Arnold
            pos_tall = None
            for k,v in height_at.items():
                if v == "tall":
                    pos_tall = k
                    break

            # Clue 1: Bob directly left of tall -> Bob at pos_tall - 1
            pos_bob = pos_tall - 1
            if pos_bob < 1:
                continue  # invalid

            # Clue 10 (already used): Xiaomi user is Carol -> Carol at pos_vt
            pos_carol = pos_vt

            # Clue 11: GP6 (4) is to the right of Eric -> Eric in {1,2,3}
            # We'll enforce during assignment.

            # Assign names by backtracking over remaining spots
            name_at = {i: None for i in houses}
            # Place forced names
            forced_positions = {}
            # Arnold at pos_tall
            forced_positions[pos_tall] = "Arnold"
            # Bob at pos_bob
            if pos_bob in forced_positions and forced_positions[pos_bob] != "Bob":
                continue
            forced_positions[pos_bob] = "Bob"
            # Carol at pos_carol
            if pos_carol in forced_positions and forced_positions[pos_carol] != "Carol":
                continue
            forced_positions[pos_carol] = "Carol"

            # Check no conflicts in forced positions
            if len(set(forced_positions.values())) != len(forced_positions.values()):
                continue

            for p, n in forced_positions.items():
                name_at[p] = n

            remaining_names = [n for n in Names if n not in forced_positions.values()]
            remaining_positions_names = [p for p in houses if name_at[p] is None]

            # Additional constraints for remaining names:
            # - Eric must be left of GP6 (at 4) -> Eric in {1,2,3}
            # - Peter left of iPhone 13 -> position(Peter) < pos_iphone
            pos_iphone = None
            for k,v in tmp_phone_at.items():
                if v == "iphone 13":
                    pos_iphone = k
                    break

            def valid_partial(n_map):
                # Check clue 2 and 11 partially if applicable
                # 11: Eric left of GP6 (4)
                if "Eric" in n_map.values():
                    for k,v in n_map.items():
                        if v == "Eric":
                            if k >= 4:
                                return False
                # 2: Peter left of iPhone 13
                if "Peter" in n_map.values():
                    for k,v in n_map.items():
                        if v == "Peter":
                            if pos_iphone is not None and k >= pos_iphone:
                                return False
                return True

            def backtrack_assign(idx, n_at, remaining_names_list, remaining_pos_list):
                if idx == len(remaining_pos_list):
                    # Completed names; verify all clues with final assignment
                    if verify_complete(n_at, height_at, tmp_phone_at):
                        solutions.append((dict(n_at), dict(height_at), dict(tmp_phone_at)))
                    return

                pos = remaining_pos_list[idx]
                for nm in list(remaining_names_list):
                    # Domain pruning:
                    # Eric must be left of 4
                    if nm == "Eric" and not (pos < 4):
                        continue
                    # Peter must be left of iPhone position
                    if nm == "Peter" and not (pos < pos_iphone):
                        continue
                    # No other immediate constraints for Alice
                    n_at[pos] = nm
                    if valid_partial(n_at):
                        next_names = remaining_names_list[:]
                        next_names.remove(nm)
                        backtrack_assign(idx+1, n_at, next_names, remaining_pos_list)
                    n_at[pos] = None

            backtrack_assign(0, name_at, remaining_names, remaining_positions_names)

            if solutions:
                # Found solution; no need to continue further permutations
                break
        if solutions:
            break
    if not solutions:
        raise RuntimeError("No solution found")

    name_at, height_at, phone_at = solutions[0]

    # Prepare JSON output
    header = ["House", "Name", "Height", "PhoneModel"]
    rows = []
    for i in houses:
        rows.append([str(i), name_at[i], height_at[i], phone_at[i]])

    result = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    solve()
